/** The first usable named credential for `provider`; unread commands are provisional unless `runCommands` is set. */
async credential(provider: string, runCommands = false): Promise<NamedCredential | undefined> {
	if (this.type(provider) === undefined) return undefined;
	for (const credential of this.named) {
		if (credential.provider !== provider) continue;
		if (credential.value.kind === "env" && (this.#env[credential.value.variable] ?? "") === "") continue;
		if (credential.value.kind === "command" && !runCommands && !this.#values.has(credential)) return credential;
		if ((await this.resolve(credential)) !== undefined) return credential;
	}
	return undefined;

/** The first model of `route` that `models` knows and holds credentials for, or `undefined` when there is none. */
static async create(
	models: ReviewModels,
	route: readonly ModelReference[],
	thinking?: ModelRoute["thinking"],
): Promise<RouteTextModel | undefined> {
	const collection = modelsOf(models);
	for (const reference of route) {
		const model = collection.getModel(reference.provider, reference.modelId);
		if (model === undefined) continue;
		// A store that cannot be read passes the provider over, so a later tier with its own credential still serves.
		if (await hasCredentials(models, reference.provider).catch(() => false))
			return new RouteTextModel(collection, model, thinking);
	}
	return undefined;
}

